func (patch biometricsBasedDetectionPatch) Apply(_ context.Context, result *client.WAFModuleResult) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if result == nil {
		diagnostics.AddError("Unable to merge biometrics based detection configuration", "The current API result was nil.")
		return diagnostics
	}
	set := func(name string, value any) {
		if err := result.SetConfig(name, value); err != nil {
			diagnostics.AddError("Unable to merge biometrics based detection configuration", fmt.Sprintf("Unable to encode %s: %v", name, err))
		}
	}
	if patch.Action.Set {
		set("action", patch.Action.Value)
	}
	if patch.BotEffectTime.Set {
		set("bot_effect_time", patch.BotEffectTime.Value)
	}
	if patch.Click.Set {
		set("click", patch.Click.Value)
	}
	if patch.EventCollectTime.Set {
		set("event_collect_time", patch.EventCollectTime.Value)
	}
	if patch.Keyboard.Set {
		set("keyboard", patch.Keyboard.Value)
	}
	if patch.MouseMovement.Set {
		set("mouse_movement", patch.MouseMovement.Value)
	}
	if patch.ScreenTouch.Set {
		set("screen_touch", patch.ScreenTouch.Value)
	}
	if patch.Scroll.Set {
		set("scroll", patch.Scroll.Value)
	}
	if patch.Status.Set {
		set("status", patch.Status.Value)
	}

	if patch.ExceptionList.Set {
		set("exception_list", patch.ExceptionList.Items)
	}

	if patch.URLList.Set {
		set("url_list", patch.URLList.Items)
	}
	return diagnostics
}

