func biometricsBasedDetectionOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (biometricsBasedDetectionOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return biometricsBasedDetectionOwnershipSet{ExceptionList: false, URLList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return biometricsBasedDetectionOwnershipSet{ExceptionList: true, URLList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return biometricsBasedDetectionOwnershipSet{ExceptionList: false, URLList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown biometrics based detection ownership", "The configs ownership state was unknown while flattening.")
		return biometricsBasedDetectionOwnershipSet{ExceptionList: false, URLList: false}, diagnostics
	}
	var configs biometricsBasedDetectionConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return biometricsBasedDetectionOwnershipSet{ExceptionList: !configs.ExceptionList.IsNull(), URLList: !configs.URLList.IsNull()}, diagnostics
}
