func biometricsBasedDetectionRejectItemNullUnlessNullable(object map[string]json.RawMessage, key string, allowNull bool, location string, diagnostics *diag.Diagnostics) {
	raw, ok := object[key]
	if !ok {
		return
	}
	if biometricsBasedDetectionJSONNull(raw) && !allowNull {
		diagnostics.AddError("Malformed biometrics based detection result", location+" "+key+" was null, which the pinned schema does not mark nullable.")
	}
}
